1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import {
5	  getMailboxSettings,
6	  saveMailboxSettings,
7	  saveAutoReply,
8	  saveForwarding,
9	  listAliases,
10	  addAlias,
11	  removeAlias,
12	  resetPassword,
13	  type MailboxSettings,
14	  type AliasRow,
15	} from "@/lib/actions-mailbox-settings";
16	import { safeHtml } from "@/lib/mail/render";
17	import {
18	  signatureHtmlToText,
19	  signatureTemplates,
20	  SIGNATURE_FONTS,
21	  SIGNATURE_SIZES,
22	  type SignaturePlacement,
23	} from "@/lib/mail/signature";
24	import { Icon } from "./util";
25	
26	/** Mail server endpoints shown in the "configure your device" panel. */
27	const MAIL_HOST = "mail.nxeon.cloud";
28	
29	type Section =
30	  | "identity"
31	  | "signature"
32	  | "autoreply"
33	  | "forwarding"
34	  | "storage"
35	  | "connection"
36	  | "aliases"
37	  | "password";
38	
39	const SECTIONS: { key: Section; label: string; short: string; icon: keyof typeof Icon }[] = [
40	  { key: "identity", label: "Identity", short: "Identity", icon: "user" },
41	  { key: "signature", label: "Signature", short: "Signature", icon: "pen" },
42	  { key: "autoreply", label: "Auto-reply", short: "Auto-reply", icon: "reply" },
43	  { key: "forwarding", label: "Forwarding", short: "Forward", icon: "forward" },
44	  { key: "storage", label: "Storage", short: "Storage", icon: "hdd" },
45	  { key: "connection", label: "Connection", short: "Connect", icon: "mail" },
46	  { key: "aliases", label: "Aliases", short: "Aliases", icon: "tag" },
47	  { key: "password", label: "Change password", short: "Password", icon: "cog" },
48	];
49	
50	export function MailSettings({
51	  mailboxAddress,
52	  storageUsedBytes,
53	  storageQuotaBytes,
54	  onClose,
55	  onSettingsChanged,
56	}: {
57	  mailboxAddress?: string;
58	  storageUsedBytes?: number;
59	  storageQuotaBytes?: number;
60	  onClose: () => void;
61	  /** Notify the parent so freshly-saved settings (signature/identity) apply to composing immediately. */
62	  onSettingsChanged?: () => void;
63	}) {
64	  const [section, setSection] = useState<Section>("signature");
65	  const [settings, setSettings] = useState<MailboxSettings | null>(null);
66	  const [loadError, setLoadError] = useState<string | null>(null);
67	
68	  useEffect(() => {
69	    let alive = true;
70	    setSettings(null);
71	    setLoadError(null);
72	    getMailboxSettings(mailboxAddress)
73	      .then((s) => alive && setSettings(s))
74	      .catch((e) => alive && setLoadError(e instanceof Error ? e.message : "Couldn't load settings."));
75	    return () => {
76	      alive = false;
77	    };
78	  }, [mailboxAddress]);
79	
80	  useEffect(() => {
81	    const onKey = (e: KeyboardEvent) => {
82	      if (e.key === "Escape") onClose();
83	    };
84	    window.addEventListener("keydown", onKey);
85	    return () => window.removeEventListener("keydown", onKey);
86	  }, [onClose]);
87	
88	  const patch = useCallback(
89	    (v: Partial<MailboxSettings>) => {
90	      setSettings((cur) => (cur ? { ...cur, ...v } : cur));
91	      onSettingsChanged?.();
92	    },
93	    [onSettingsChanged],
94	  );
95	
96	  return (
97	    <div
98	      className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4"
99	      role="dialog"
100	      aria-modal="true"
101	      aria-label="Mailbox settings"
102	      onClick={onClose}
103	    >
104	      <div
105	        className="glass flex h-[92vh] w-full max-w-4xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-[86vh]"
106	        onClick={(e) => e.stopPropagation()}
107	      >
108	        {/* Header */}
109	        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
110	          <div className="min-w-0">
111	            <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
112	              <span className="text-brand-300"><Icon.cog size={16} /></span>
113	              Mailbox settings
114	            </h3>
115	            {settings && (
116	              <p className="mt-0.5 truncate text-xs text-slate-500" title={settings.address}>
117	                {settings.address}
118	              </p>
119	            )}
120	          </div>
121	          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
122	            <Icon.close size={16} />
123	          </button>
124	        </div>
125	
126	        <div className="flex min-h-0 flex-1 flex-col sm:flex-row">
127	          {/* Section nav */}
128	          <nav className="flex flex-none gap-1 overflow-x-auto border-b border-white/[0.06] p-2 sm:w-52 sm:flex-col sm:overflow-x-visible sm:overflow-y-auto sm:border-b-0 sm:border-r">
129	            {SECTIONS.map((s) => {
130	              const Ico = Icon[s.icon];
131	              const active = section === s.key;
132	              return (
133	                <button
134	                  key={s.key}
135	                  onClick={() => setSection(s.key)}
136	                  className={`flex flex-none items-center gap-2.5 whitespace-nowrap rounded-xl px-3 py-2 text-sm font-medium transition-colors ${
137	                    active ? "nav-item-active" : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
138	                  }`}
139	                >
140	                  <Ico size={16} className={active ? "text-white" : ""} />
141	                  <span className="hidden sm:inline">{s.label}</span>
142	                  <span className="sm:hidden">{s.short}</span>
143	                </button>
144	              );
145	            })}
146	          </nav>
147	
148	          {/* Section content */}
149	          <div className="min-h-0 flex-1 overflow-y-auto p-5">
150	            {loadError ? (
151	              <ErrorNote text={loadError} />
152	            ) : !settings ? (
153	              <LoadingRows />
154	            ) : section === "identity" ? (
155	              <IdentitySection mailboxAddress={mailboxAddress} initial={settings} onSaved={patch} />
156	            ) : section === "signature" ? (
157	              <SignatureSection mailboxAddress={mailboxAddress} initial={settings} onSaved={patch} />
158	            ) : section === "autoreply" ? (
159	              <AutoReplySection mailboxAddress={mailboxAddress} initial={settings} onSaved={patch} />
160	            ) : section === "forwarding" ? (
161	              <ForwardingSection mailboxAddress={mailboxAddress} initial={settings} onSaved={patch} />
162	            ) : section === "storage" ? (
163	              <StorageSection
164	                initial={settings}
165	                usedBytes={storageUsedBytes}
166	                quotaBytes={storageQuotaBytes}
167	              />
168	            ) : section === "connection" ? (
169	              <ConnectionSection address={settings.address} />
170	            ) : section === "aliases" ? (
171	              <AliasesSection mailboxAddress={mailboxAddress} domain={settings.domain} />
172	            ) : (
173	              <PasswordSection mailboxAddress={mailboxAddress} />
174	            )}
175	          </div>
176	        </div>
177	      </div>
178	    </div>
179	  );
180	}
181	
182	/* -------------------------------------------------------------------------- */
183	/* Section: Identity                                                           */
184	/* -------------------------------------------------------------------------- */
185	
186	function IdentitySection({
187	  mailboxAddress,
188	  initial,
189	  onSaved,
190	}: {
191	  mailboxAddress?: string;
192	  initial: MailboxSettings;
193	  onSaved: (v: Partial<MailboxSettings>) => void;
194	}) {
195	  const [displayName, setDisplayName] = useState(initial.displayName);
196	  const [replyTo, setReplyTo] = useState(initial.replyTo);
197	  const [organization, setOrganization] = useState(initial.organization);
198	  const [saving, setSaving] = useState(false);
199	  const [msg, setMsg] = useState<string | null>(null);
200	  const [err, setErr] = useState<string | null>(null);
201	
202	  async function save() {
203	    setSaving(true);
204	    setMsg(null);
205	    setErr(null);
206	    try {
207	      const res = await saveMailboxSettings({ displayName, replyTo, organization }, mailboxAddress);
208	      if (!res.ok) setErr(res.error || "Couldn't save.");
209	      else {
210	        setMsg("Saved.");
211	        onSaved({ displayName: displayName.trim(), replyTo: replyTo.trim(), organization: organization.trim() });
212	      }
213	    } catch (e) {
214	      setErr(e instanceof Error ? e.message : "Couldn't save.");
215	    } finally {
216	      setSaving(false);
217	    }
218	  }
219	
220	  return (
221	    <div className="space-y-5">
222	      <SectionHead title="Identity" sub="How you appear to people you email from this mailbox." />
223	
224	      <div>
225	        <label className="label" htmlFor="ms-name">Display name</label>
226	        <input
227	          id="ms-name"
228	          className="input"
229	          value={displayName}
230	          onChange={(e) => setDisplayName(e.target.value)}
231	          placeholder="e.g. Jane Doe"
232	          maxLength={120}
233	        />
234	        <p className="mt-1.5 text-xs text-slate-500">Shown as the sender name on messages you send.</p>
235	      </div>
236	
237	      <div>
238	        <label className="label" htmlFor="ms-org">Organization</label>
239	        <input
240	          id="ms-org"
241	          className="input"
242	          value={organization}
243	          onChange={(e) => setOrganization(e.target.value)}
244	          placeholder="e.g. Acme Inc."
245	          maxLength={200}
246	        />
247	      </div>
248	
249	      <div>
250	        <label className="label" htmlFor="ms-replyto">Reply-to address</label>
251	        <input
252	          id="ms-replyto"
253	          className="input"
254	          value={replyTo}
255	          onChange={(e) => setReplyTo(e.target.value)}
256	          placeholder="Leave blank to use your own address"
257	          maxLength={200}
258	          inputMode="email"
259	        />
260	        <p className="mt-1.5 text-xs text-slate-500">Replies are directed here instead of your sending address.</p>
261	      </div>
262	
263	      <div>
264	        <label className="label">Sending address</label>
265	        <CopyField label="From" value={initial.address} mono />
266	      </div>
267	
268	      <SaveRow saving={saving} msg={msg} err={err} onSave={save} />
269	    </div>
270	  );
271	}
272	
273	/* -------------------------------------------------------------------------- */
274	/* Section: Signature (rich editor)                                            */
275	/* -------------------------------------------------------------------------- */
276	
277	/** Escape a value for safe interpolation into a double-quoted HTML attribute. */
278	function escAttr(v: string): string {
279	  return v
280	    .replace(/&/g, "&amp;")
281	    .replace(/"/g, "&quot;")
282	    .replace(/</g, "&lt;")
283	    .replace(/>/g, "&gt;");
284	}
285	
286	/** Escape plain text into HTML for the legacy-plain -> HTML seeding path. */
287	function plainToHtml(plain: string): string {
288	  const esc = plain.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
289	  return `<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;color:#334155">${esc.replace(/\n/g, "<br>")}</div>`;
290	}
291	
292	function SignatureSection({
293	  mailboxAddress,
294	  initial,
295	  onSaved,
296	}: {
297	  mailboxAddress?: string;
298	  initial: MailboxSettings;
299	  onSaved: (v: Partial<MailboxSettings>) => void;
300	}) {
301	  const editorRef = useRef<HTMLDivElement | null>(null);
302	  const savedRange = useRef<Range | null>(null);
303	  const fileInputRef = useRef<HTMLInputElement | null>(null);
304	  const [uploading, setUploading] = useState(false);
305	  const [imgErr, setImgErr] = useState<string | null>(null);
306	
307	  const seedHtml =
308	    (initial.signatureHtml && safeHtml(initial.signatureHtml)) ||
309	    (initial.signature ? plainToHtml(initial.signature) : "");
310	
311	  const [html, setHtml] = useState(seedHtml); // mirrors editor content, for preview + save
312	  const [enabled, setEnabled] = useState(initial.signatureEnabled);
313	  const [onReply, setOnReply] = useState(initial.signatureOnReply);
314	  const [placement, setPlacement] = useState<SignaturePlacement>(initial.signaturePlacement);
315	  const [saving, setSaving] = useState(false);
316	  const [msg, setMsg] = useState<string | null>(null);
317	  const [err, setErr] = useState<string | null>(null);
318	
319	  // Seed the contentEditable once (React never re-writes it, so the caret is safe).
320	  useEffect(() => {
321	    if (editorRef.current) editorRef.current.innerHTML = seedHtml;
322	    // eslint-disable-next-line react-hooks/exhaustive-deps
323	  }, []);
324	
325	  const sync = useCallback(() => setHtml(editorRef.current?.innerHTML ?? ""), []);
326	
327	  const saveSel = useCallback(() => {
328	    const sel = window.getSelection();
329	    if (sel && sel.rangeCount > 0) {
330	      const r = sel.getRangeAt(0);
331	      if (editorRef.current && editorRef.current.contains(r.commonAncestorContainer)) {
332	        savedRange.current = r.cloneRange();
333	      }
334	    }
335	  }, []);
336	
337	  const restoreSel = useCallback(() => {
338	    const el = editorRef.current;
339	    if (!el) return;
340	    el.focus();
341	    const sel = window.getSelection();
342	    if (savedRange.current && sel) {
343	      try {
344	        sel.removeAllRanges();
345	        sel.addRange(savedRange.current);
346	      } catch {
347	        /* range detached — leave caret where it is */
348	      }
349	    }
350	  }, []);
351	
352	  // Run an execCommand, degrading gracefully if the browser doesn't support it.
353	  const exec = useCallback(
354	    (cmd: string, value?: string) => {
355	      try {
356	        restoreSel();
357	        document.execCommand(cmd, false, value);
358	      } catch {
359	        /* unsupported command — ignore rather than crash the editor */
360	      }
361	      saveSel();
362	      sync();
363	    },
364	    [restoreSel, saveSel, sync],
365	  );
366	
367	  const insertHtml = useCallback(
368	    (fragment: string) => {
369	      const el = editorRef.current;
370	      if (!el) return;
371	      restoreSel();
372	      let ok = false;
373	      try {
374	        ok = document.execCommand("insertHTML", false, fragment);
375	      } catch {
376	        ok = false;
377	      }
378	      if (!ok) el.innerHTML = el.innerHTML + fragment; // fallback: append
379	      saveSel();
380	      sync();
381	    },
382	    [restoreSel, saveSel, sync],
383	  );
384	
385	  function promptLink() {
386	    const url = window.prompt("Link URL", "https://");
387	    if (!url) return;
388	    exec("createLink", url.trim());
389	  }
390	
391	  function promptImage() {
392	    const url = window.prompt("Image URL (https://…)", "https://");
393	    if (!url) return;
394	    setImgErr(null);
395	    insertHtml(`<img src="${escAttr(url.trim())}" style="max-width:100%" />`);
396	  }
397	
398	  // Primary path: open the OS file picker to upload an image from the computer.
399	  function pickImage() {
400	    setImgErr(null);
401	    saveSel(); // remember the caret before the file dialog steals focus
402	    fileInputRef.current?.click();
403	  }
404	
405	  async function onImageFile(e: React.ChangeEvent<HTMLInputElement>) {
406	    const file = e.target.files?.[0];
407	    e.target.value = ""; // allow re-picking the same file later
408	    if (!file) return;
409	
410	    setImgErr(null);
411	    setUploading(true);
412	    try {
413	      const body = new FormData();
414	      body.append("file", file);
415	      const res = await fetch("/api/mail/signature-image", { method: "POST", body });
416	      const data = (await res.json().catch(() => ({}))) as { url?: string; error?: string };
417	      if (!res.ok || !data.url) {
418	        setImgErr(data.error || "Couldn't upload that image.");
419	        return;
420	      }
421	      // Insert at the saved caret so the dialog's focus loss doesn't drop it.
422	      insertHtml(`<img src="${escAttr(data.url)}" style="max-width:100%" />`);
423	    } catch {
424	      setImgErr("Couldn't upload that image. Please try again.");
425	    } finally {
426	      setUploading(false);
427	    }
428	  }
429	
430	  function clearFormatting() {
431	    exec("removeFormat");
432	    exec("unlink");
433	  }
434	
435	  async function save() {
436	    setSaving(true);
437	    setMsg(null);
438	    setErr(null);
439	    try {
440	      const clean = safeHtml(editorRef.current?.innerHTML ?? "");
441	      const res = await saveMailboxSettings(
442	        { signatureHtml: clean, signatureEnabled: enabled, signatureOnReply: onReply, signaturePlacement: placement },
443	        mailboxAddress,
444	      );
445	      if (!res.ok) {
446	        setErr(res.error || "Couldn't save.");
447	      } else {
448	        setMsg("Saved.");
449	        setHtml(clean);
450	        onSaved({
451	          signatureHtml: clean,
452	          signature: signatureHtmlToText(clean),
453	          signatureEnabled: enabled,
454	          signatureOnReply: onReply,
455	          signaturePlacement: placement,
456	        });
457	      }
458	    } catch (e) {
459	      setErr(e instanceof Error ? e.message : "Couldn't save.");
460	    } finally {
461	      setSaving(false);
462	    }
463	  }
464	
465	  const templates = signatureTemplates({
466	    name: initial.displayName,
467	    org: initial.organization,
468	    email: initial.address,
469	  });
470	  const previewHtml = safeHtml(html);
471	
472	  return (
473	    <div className="space-y-5">
474	      <SectionHead
475	        title="Signature"
476	        sub="Design a rich signature that's added to messages you send. Formatting, links and images are supported."
477	      />
478	
479	      <Toggle
480	        label={`Signature ${enabled ? "on" : "off"}`}
481	        checked={enabled}
482	        onChange={() => setEnabled((v) => !v)}
483	      />
484	
485	      <div className={enabled ? "space-y-4" : "space-y-4 opacity-60"}>
486	        {/* Editor */}
487	        <div className="overflow-hidden rounded-xl border border-white/10">
488	          {/* Toolbar */}
489	          <div className="flex flex-wrap items-center gap-0.5 border-b border-white/10 bg-navy-900/90 px-2 py-1.5">
490	            <TBtn title="Bold" onClick={() => exec("bold")}>
491	              <span className="text-[15px] font-bold">B</span>
492	            </TBtn>
493	            <TBtn title="Italic" onClick={() => exec("italic")}>
494	              <span className="text-[15px] font-serif italic">I</span>
495	            </TBtn>
496	            <TBtn title="Underline" onClick={() => exec("underline")}>
497	              <span className="text-[15px] underline">U</span>
498	            </TBtn>
499	            <Sep />
500	            <select
501	              aria-label="Font"
502	              className="h-8 rounded-lg border border-white/10 bg-navy-800 px-1.5 text-xs text-slate-200 outline-none"
503	              defaultValue=""
504	              onChange={(e) => {
505	                if (e.target.value) exec("fontName", e.target.value);
506	                e.target.value = "";
507	              }}
508	            >
509	              <option value="" disabled>Font</option>
510	              {SIGNATURE_FONTS.map((f) => (
511	                <option key={f.label} value={f.css}>{f.label}</option>
512	              ))}
513	            </select>
514	            <select
515	              aria-label="Text size"
516	              className="h-8 rounded-lg border border-white/10 bg-navy-800 px-1.5 text-xs text-slate-200 outline-none"
517	              defaultValue=""
518	              onChange={(e) => {
519	                if (e.target.value) exec("fontSize", e.target.value);
520	                e.target.value = "";
521	              }}
522	            >
523	              <option value="" disabled>Size</option>
524	              {SIGNATURE_SIZES.map((s) => (
525	                <option key={s.value} value={s.value}>{s.label}</option>
526	              ))}
527	            </select>
528	            <label
529	              title="Text color"
530	              className="flex h-8 w-8 cursor-pointer items-center justify-center rounded-lg text-slate-300 hover:bg-white/10"
531	            >
532	              <span className="text-[13px] font-semibold">A</span>
533	              <span className="-mt-1 block h-1 w-3 rounded bg-brand-400" />
534	              <input
535	                type="color"
536	                className="absolute h-0 w-0 opacity-0"
537	                onChange={(e) => exec("foreColor", e.target.value)}
538	              />
539	            </label>
540	            <Sep />
541	            <TBtn title="Bulleted list" onClick={() => exec("insertUnorderedList")}>
542	              <ListIcon ordered={false} />
543	            </TBtn>
544	            <TBtn title="Numbered list" onClick={() => exec("insertOrderedList")}>
545	              <ListIcon ordered />
546	            </TBtn>
547	            <Sep />
548	            <TBtn title="Insert link" onClick={promptLink}>
549	              <LinkIcon />
550	            </TBtn>
551	            <TBtn
552	              title={uploading ? "Uploading…" : "Upload image from your computer"}
553	              onClick={pickImage}
554	              disabled={uploading}
555	            >
556	              {uploading ? <SpinnerIcon /> : <ImageIcon />}
557	            </TBtn>
558	            <button
559	              type="button"
560	              title="Insert image by URL instead"
561	              onMouseDown={(e) => e.preventDefault()}
562	              onClick={promptImage}
563	              className="flex h-8 items-center rounded-lg px-1.5 text-[11px] font-medium text-slate-500 transition-colors hover:bg-white/10 hover:text-slate-200"
564	            >
565	              URL
566	            </button>
567	            <input
568	              ref={fileInputRef}
569	              type="file"
570	              accept="image/png,image/jpeg,image/gif,image/webp"
571	              className="hidden"
572	              onChange={onImageFile}
573	            />
574	            <TBtn title="Horizontal rule" onClick={() => exec("insertHorizontalRule")}>
575	              <span className="text-base leading-none">—</span>
576	            </TBtn>
577	            <Sep />
578	            <TBtn title="Clear formatting" onClick={clearFormatting}>
579	              <ClearIcon />
580	            </TBtn>
581	          </div>
582	
583	          {/* Inline upload error (size/type) */}
584	          {imgErr && (
585	            <div className="border-b border-red-500/20 bg-red-500/[0.08] px-4 py-2 text-xs text-red-300">
586	              {imgErr}
587	            </div>
588	          )}
589	
590	          {/* contentEditable — white surface so it matches what recipients see */}
591	          <div
592	            ref={editorRef}
593	            contentEditable
594	            suppressContentEditableWarning
595	            role="textbox"
596	            aria-multiline="true"
597	            aria-label="Signature editor"
598	            onInput={sync}
599	            onKeyUp={saveSel}
600	            onMouseUp={saveSel}
601	            onBlur={saveSel}
602	            className=" nx-sig-editor min-h-[10rem] max-h-[22rem] w-full overflow-auto bg-white px-4 py-3 text-sm leading-relaxed text-slate-900 outline-none"
603	          />
604	        </div>
605	
606	        {/* Templates */}
607	        <div>
608	          <p className="section-label mb-2">Start from a template</p>
609	          <div className="flex flex-wrap gap-2">
610	            {templates.map((t) => (
611	              <button
612	                key={t.id}
613	                type="button"
