863	function fmtBytes(n: number): string {
864	  if (!Number.isFinite(n) || n <= 0) return "0 MB";
865	  const units = ["B", "KB", "MB", "GB", "TB"];
866	  let v = n;
867	  let i = 0;
868	  while (v >= 1024 && i < units.length - 1) {
869	    v /= 1024;
870	    i++;
871	  }
872	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
873	}
