889	        : 0;
890	  const used = usedBytes && usedBytes > 0 ? usedBytes : 0;
891	  const haveUsage = usedBytes !== undefined;
892	  const pct = quota > 0 ? Math.min(100, Math.round((used / quota) * 100)) : 0;
893	  const nearFull = pct >= 90;
