900	        <div className="flex items-baseline justify-between">
901	          <span className="text-2xl font-semibold text-white">{fmtBytes(used)}</span>
902	          <span className="text-sm text-slate-400">of {quota > 0 ? fmtBytes(quota) : "—"}</span>
903	        </div>
904	
905	        <div className="mt-3 h-2.5 w-full overflow-hidden rounded-full bg-white/10">
