908	            style={{ width: `${quota > 0 ? pct : 0}%` }}
909	          />
910	        </div>
911	
912	        <p className="mt-2 text-xs text-slate-500">
913	          {quota > 0 ? `${pct}% used` : "Quota not set"}
914	          {!haveUsage && " — live usage is unavailable right now; showing your plan quota."}
