// Read the editor HTML with editor-only artifacts (the image selection ring class)
// stripped, so the stored signature never carries a selection outline or empty class.
const getCleanHtml = useCallback(() => {
  const el = editorRef.current;
  if (!el) return "";
  const clone = el.cloneNode(true) as HTMLElement;
  clone.querySelectorAll("img").forEach((im) => {
    im.classList.remove("nx-img-active");
    if (!im.getAttribute("class")) im.removeAttribute("class");
  });
  return clone.innerHTML;
}, []);

const sync = useCallback(() => setHtml(getCleanHtml()), [getCleanHtml]);

// Highlight an image as the active one (adds the editor-only ring class) and
// initialise the size control from its current inline width.
const selectImg = useCallback((img: HTMLImageElement) => {
  const el = editorRef.current;
  if (el) el.querySelectorAll("img.nx-img-active").forEach((i) => i.classList.remove("nx-img-active"));
  img.classList.add("nx-img-active");
  const sw = img.style.width.trim();
  const full = sw === "100%";
  let w = 0;
  if (sw.endsWith("px")) w = parseInt(sw, 10);
  if (!w) w = Math.round(img.getBoundingClientRect().width) || img.naturalWidth || 320;
  setActiveImg(img);
  setImgFull(full);
  setImgWidth(clampImgWidth(w));
}, []);

const deselectImg = useCallback(() => {
  const el = editorRef.current;
  if (el)
    el.querySelectorAll("img.nx-img-active").forEach((i) => {
      i.classList.remove("nx-img-active");
      if (!i.getAttribute("class")) i.removeAttribute("class");
    });
  setActiveImg(null);
}, []);

// Apply a fixed pixel width, keeping max-width:100% + height:auto so it never
