const applyImgWidth = useCallback(
  (px: number) => {
    const img = activeImg;
    if (!img) return;
    const w = clampImgWidth(px);
    img.style.width = `${w}px`;
    img.style.maxWidth = "100%";
    img.style.height = "auto";
    setImgFull(false);
    setImgWidth(w);
    sync();
  },
  [activeImg, sync],
);

const applyImgFull = useCallback(() => {
  const img = activeImg;
  if (!img) return;
  img.style.width = "100%";
  img.style.maxWidth = "100%";
  img.style.height = "auto";
  setImgFull(true);
  sync();
}, [activeImg, sync]);

const resetImgSize = useCallback(() => {
  const img = activeImg;
  if (!img) return;
  img.style.width = "";
  img.style.maxWidth = "100%";
  img.style.height = "auto";
  setImgFull(false);
