      onClick={onClick}
      aria-pressed={active}
      className={`flex h-8 items-center rounded-lg px-2.5 text-[11px] font-medium transition-colors ${
        active ? "bg-brand-500 text-white" : "text-slate-300 hover:bg-white/10 hover:text-white"
      }`}
    >
      {children}
    </button>
  );
}

function Sep() {
  return <span className="mx-1 h-5 w-px flex-none bg-white/10" />;
}
